import{_ as a,o,c as t,ag as r}from"./chunks/framework.DQQHyi2x.js";const d=JSON.parse('{"title":"Backup & Restore","description":"","frontmatter":{},"headers":[],"relativePath":"features/backup.md","filePath":"features/backup.md"}'),i={name:"features/backup.md"};function n(s,e,l,c,u,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="backup-restore" tabindex="-1">Backup &amp; Restore <a class="header-anchor" href="#backup-restore" aria-label="Permalink to &quot;Backup &amp; Restore&quot;">​</a></h1><p>Create and manage configuration backups with selective component restore.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Backup page lets you create ZIP archives of your Claude Code configuration, restore from backups, and manage backup history.</p><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="creating-a-backup" tabindex="-1">Creating a Backup <a class="header-anchor" href="#creating-a-backup" aria-label="Permalink to &quot;Creating a Backup&quot;">​</a></h3><p>Click <strong>&quot;Create Backup&quot;</strong> to open the wizard:</p><ol><li><strong>Select components</strong> — choose what to include: <ul><li>Agents</li><li>Skills</li><li>Commands</li><li>Plugins</li><li>Hooks</li><li>Rules</li><li>MCP server configs</li></ul></li><li><strong>Name &amp; Description</strong> — label your backup</li><li>Click create to generate the ZIP archive</li></ol><h3 id="restoring-from-backup" tabindex="-1">Restoring from Backup <a class="header-anchor" href="#restoring-from-backup" aria-label="Permalink to &quot;Restoring from Backup&quot;">​</a></h3><p>Click <strong>Restore</strong> on any backup to open the restore wizard:</p><ol><li>Review the backup contents and component list</li><li>Check for dependency warnings (missing plugins or MCP servers)</li><li>Confirm the restore</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Restoring overwrites existing configuration files for the selected components. Make a backup of your current configuration first if needed.</p></div><h3 id="managing-backups" tabindex="-1">Managing Backups <a class="header-anchor" href="#managing-backups" aria-label="Permalink to &quot;Managing Backups&quot;">​</a></h3><ul><li><strong>Download</strong> — save the ZIP archive to your local machine</li><li><strong>Delete</strong> — remove a backup from the system</li></ul><p>Stat cards at the top show total backups, combined size, and count with external dependencies.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Backups are stored in <code>~/.claude-registry/backups/</code> as ZIP files with a JSON manifest containing metadata, component list, and dependency information.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Regular backups</strong> before major configuration changes protect against mistakes.</li><li>The dependency checker warns you about plugins or MCP servers that need to be installed before restoring.</li><li>Backups include platform info — restore warnings may appear when moving between operating systems.</li></ul>',19)])])}const g=a(i,[["render",n]]);export{d as __pageData,g as default};
